110		* register()
111		* registro un utente
112		* @param void
113		* @return int 0 insuccesso || 1 successo
114		*/
115		public function register(){
116	
117		    $result = $this->MailChimp->call('lists/subscribe', $this->arRegistrationArgs);
118		    if (
119		        empty($result["email"])
120		        || (!empty($result["status"]) &&  $result["status"] == 'error')
121		    ):
122				throw new \Exception('['.__METHOD__.'] ERRORE ISCRIZIONE: Risposta completa: <pre>'.print_r($result,1).'</pre>',E_USER_WARNING);
123		    	return 0;
124		    else:
125		        return 1;
126		    endif;
127		}
