135		*/
136		public function setMemberInfoArgs($arArgs){
137			if($arArgs && is_array($arArgs)):
138		        foreach($arArgs as $ka => $va):
139		            $this->setMemberInfoArg($ka,$va);
140		        endforeach;
141			endif;
142		}
