156	
157		/**
158		* resetMemberInfoArgs()
159		* imposto il valore di un elemento dell'array di informazioni
160		* @param string $key: chiave dell'elemento da impostare
161		* @param string $val: valore 
162		* @return void
163		*/
164		public function resetMemberInfoArgs(){
165			$this->arMemberInfoArgs = array(
166		        'id'   			=> NULL
167		        ,'emails'         	=> array()
168			);
169		}
170	
171		public function memberInfo(){
172		    return $this->MailChimp->call('lists/member-info', $this->arMemberInfoArgs);
173		}
174	
175		public function isUserRegistered(){
176			$result = $this->memberInfo();
177		    return $result['success_count'] > 0 ? 1 : 0;
178		}
