180	
181		/**
182		* setMergeVars()
183		* imposto il valore di un elemento dell'array di informazioni
184		* @param array $data: array formato dai dati da passare alla lista: la chiave dovrà corrispondere ad un valore dell'array $MailChimp_Form_Data_Match
185		* @return array $merge_vars: l'array merge vars che errà passato alla lista
186		*/
187		public function setMergeVars($data = array()){
188			$to_return = array();
189			if(isset($data) && is_array($data) && count($data) > 0):
190				foreach($data as $k => $v):
191					$merge_key = array_search($k,$this->MailChimp_Form_Data_Match);
192					if($merge_key !== false):
193						$to_return[$merge_key] = $v;
194					endif;
195				endforeach;
196			endif;
197			ksort($to_return);
198			return $to_return;
199		}
