2	/**
3	 * LangManager
4	 * -----------------------------------------------------------------------------------------------
5	 * Gestisce traduzioni dei testi e dei link
6	 * 
7	 * carica traduzioni attraverso LoadTrads 
8	 * carica link attraverso LoadLinks (mantengo due metodi separati per poter usare flessibilmente la classe in casi in cui si necessiti solo delle
9	 * traduzioni o solo dei link.)
10	 * memorizza variabili d'ambiente (formato numeri, dati, ciò che si vuole..) per le funzioni o gli script che ne hanno bisogno
11	 * esempio d'uso :
12	 *  $Lang->loadTrads();                     | posso chiamare questi due metodi indipendentemente a seconda del bisogno
13	 *  $Lang->loadLinks();                     |
14	 * 
15	 * @dipendenze
16	 * Da -> DataAccess per accesso al db
17	 * 
18	 * @author Emanuele Fornasier, Jacopo Viscuso
19	 * @version 2018/11/28
20	 *      
21	 * 
22	 * TODO:
23	 * dividere la logica della gestione lingua da quella della gestione link (es. priority)
24	 * ( creare altra classe ??)
25	 * =================================================================================================================================================
26	*/
27	
28	class LangManager {
29	    
30	    private $linkLoaded = false;            //| per evitare doppie chiamate al db
31	    private $tradLoaded = false;            //|
32	    
33	    private $strError = '';                 // stringa degli errori (output nel distruttore)
34	    private $arRewrite = array();           // array delle regole di rewrite
35	    private $lgList = array();              // array(id => suff) di tutte le lingue
36	    private $lgTagList = array();           // array dei tag lingua internazionali
37	    private $arLinks = array();             // array dei link
38	    private $arTrads = array();             // array delle traduz.
39	    private $groupList = '';                // lista dei gruppi (per switchLanguage)
40	    
41	    protected $pdo;
42	
43	    public $lgId;                           // id lingua attiva
44	    public $lgSuff;                         // suff lingua attiva
45	    public $lgTag;                          // suff per indicazione codifica
46	    private $_activeLinkKey = null;             // key del link attivo
47	    
48	    private $scriptName = false;            // per impostare link attivi
49	    private $arOptions = array (
50	        'display_errors' => 0
51	        ,'language_tags' => 0
52	        ,'base_url' => ''
53	        // nome tabella concatenata a colonna per filtrare lingue attive
54	        ,'table_lg' => 'lang.active'
55	        ,'table_link' => 'lang_link'
56	        ,'table_trad' => 'lang_trad'
57	        // se impostato a stringa, forza il caricamento di quella lingua
58	        ,'force_language' => false
59	        
60	        // se impostato a stringa, forza il caricamento di quella lingua
61	        ,'default_language' => 'it'
62	        
63	        // gruppi caricati di default (separati da virgola)
64	        ,'groups' => "global"
65	        
66	        // abilita cartella lingua
67	        ,'enable_language_dir' => true
68	
69	        // sorgente traduzioni (file/database)
70	        ,"lang_source" => 'file'
71	        // path base per export/import traduzioni
72	        ,"lang_export_folder" => null
73	        
74	    );
75	
76	
77	    /**
78	     * array interno dei link alternativi in lingua
79	     */
80	    private $lgAlternates;
81	
82	
83	    /**
84	     * @var pdo PDO instance
85	     * @var options array
86	     */
87	    public function __construct($pdo, array $options = array()) {
88	
89	    
90	        // Connessione db
91	        $this->pdo = $pdo;
92	
93	        // Opzioni
94	        if ($options) :
95	            $this->arOptions = array_merge($this->arOptions, $options);
96	        endif;
97	        
98	        // Lingue disponibili
99	        $option = explode(".", $this->arOptions["table_lg"]);
100	        $table = $option[0];
101	        $active = isset($option[1]) ? $option[1] : 'active';
102	
103	        $result = $this->pdo->query('SELECT * FROM '.$table.' WHERE '.$active.' = 1 ORDER BY position ASC', PDO::FETCH_OBJ);
104	        foreach ($result as $key => $rs): 
105	            // lista suffissi
106	            $this->lgList[$rs->id] = $rs->suffix;
107	
108	            //lista info
109	            $this->lgRecord[$rs->id] = array();
110	            foreach ( $rs as $k => $v) :
111	                $this->lgRecord[$rs->id][$k] = $v;
112	            endforeach;
113	            
114	        endforeach;     
115	
116	        // suffisso lingua (ita di default - cerco e imposto anche in sessione per eventuali altri script )
117	        $request_uri = !empty($_SERVER['REQUEST_URI']) ? str_replace($this->arOptions["base_url"], '', $_SERVER['REQUEST_URI']) : '';
118	        $dati_url = explode('/', $request_uri);
119	       
120	        // se ho passato forzatura lingua, la uso            
121	        if ($this->arOptions["force_language"] && strlen($this->arOptions["force_language"]) ) :
122	            $_SESSION['lgSuff'] = $this->lgSuff = $this->arOptions["force_language"];
123	        else : 
124	            $_SESSION['lgSuff'] = $this->lgSuff = 
125	                    !empty($dati_url[1]) && in_array($dati_url[1], $this->lgList)
126	                ?   $dati_url[1]
127	                :   (
128	                            !empty($_SESSION['lgSuff']) && in_array($_SESSION['lgSuff'], $this->lgList)
129	                        ?   $_SESSION['lgSuff']
130	                        :   $this->arOptions["default_language"]
131	                    )
132	            ;
133	        endif;
134	
135	
136	        // Id lingua
137	        $this->lgId = in_array($this->lgSuff, $this->lgList) ? array_search($this->lgSuff, $this->lgList) : 1;
138	        if ($this->arOptions['language_tags'] && isset($this->lgRecord[$this->lgId])) {$this->lgTag = $this->lgRecord[$this->lgId]["language_tag"];}
139	
140	    }
141	    
142	    public function __destruct() {
143	        if ($this->arOptions['display_errors'] && $this->strError) {echo $this->strError;}
144	    }
145	    
146	    public function setOption($name, $value) {
147	        if (array_key_exists($name,$this->arOptions)) {
148	            $this->arOptions[$name] = $value;
149	        }
150	    }
151	    
152	
153	    /**
154	     * carica link in variabile interna
155	     * La priortià col valore più alto va in cima, risultando prioritaria nella mappatura dei link per il router
156	     * (nel caso che più espressioni regolari combacino con l'url)
157	     */
158	    public function loadLinks() {
159	
160	        /**
161	         * Se ho selezionato sorgente file
162	         */
163	        if($this->arOptions["lang_source"] === 'file') {
164	            $result = json_decode(file_get_contents($this->arOptions["lang_export_folder"]."/links.json"), true);
165	            if(!$result) {
166	                throw new Exception('Errore recupero link per lettura');
167	            }
168	
169	            // ordino manualmente per priorita (in linea con recupero da database)
170	            usort($result, function($a, $b) {
171	                if ($a['priority'] == $b['priority']) {
172	                    return 0;
173	                }
174	                return ($a['priority'] > $b['priority']) ? -1 : 1;
175	            });
176	
177	        } else {
178	            $result = $this->pdo->query('SELECT * FROM '.$this->arOptions["table_link"].' ORDER BY priority DESC', PDO::FETCH_ASSOC);
179	        }
180	
181	        $defult_enable_language_dir = $this->arOptions["enable_language_dir"];
182	        foreach ($result as $key => $rs): 
183	            
184	            $link = $this->parseLinkOnLoad($rs['link_'.$this->lgSuff]);
185	
186	            // memorizzo array su key "code"
187	            $this->arLinks[$rs['code']]['link'] = $link; 
188	            $this->arLinks[$rs['code']]['filename'] = $rs['filename'];
189	            $this->arLinks[$rs['code']]['pattern'] = preg_match("#\(([^\)]+)\)#", $link) ? 1 : 0;
190	            
191	            // memorizzo array su key "link" per avere rapido accesso al file corrispondente
192	            $this->arFiles[$link] = $rs['filename'];
193	
194	            // memorizzo alternates
195	            $this->arAlternates[$rs["code"]] = array();
196	            foreach ($this->lgRecord as $key => $lg) {
197	                $this->arAlternates[$rs['code']][$lg["suffix"]] = $this->parseLinkOnLoad($rs["link_".$lg["suffix"]], $lg["suffix"]);
198	            }
199	
200	        endforeach;
201	
202	        unset($result);
203	        unset($rs);
204	        
205	        $this->linkLoaded = true;
206	
207	    }
208	
209	
210	    /**
211	     * separa logica di generazione del link
212	     * dal valore in db
213	     */
214	    protected function parseLinkOnLoad($dbValue, $lgSuff = '') {
215	
216	        // se non ho richiesto suffisso specifico uso quello attivo
217	        $lgSuff = $lgSuff ?: $this->lgSuff;
218	
219	        $suffLink = $this->arOptions["enable_language_dir"] ? '/'.$lgSuff : '';
220	
221	
222	        // mantengo i link assoluti
223	        return
224	            strstr($dbValue, 'http://') || strstr($dbValue, 'https://')
225	            ?   $dbValue
226	            :   $this->arOptions["base_url"].$suffLink.$dbValue
227	        ; 
228	
229	    }
230	
231	
232	    /**
233	     * carica link in variabile interna
234	     * carica SEMPRE traduzioni con key "global"
235	     * @var groupList lista dei gruppo separati da virgola
236	     */
237	    public function loadTrads ($groupList = '') {
238	
239	        /**
240	         * Se ho selezionato sorgente file, le recupero tutte e poi le filtro
241	         */
242	        if($this->arOptions["lang_source"] === 'file') {
243	            $trads = json_decode(file_get_contents($this->arOptions["lang_export_folder"]."/trads.json"), true);
244	            if(!$trads) {
245	                throw new Exception('Errore recupero traduzioni per lettura');
246	            }
247	        }
248	        
249	        $this->groupList = !empty($groupList) ? $groupList : $this->groupList;
250	
251	        // aggiungo gruppi di default
252	        if (strlen($this->arOptions["groups"])) :
253	            $this->groupList = $this->arOptions["groups"].",".$this->groupList;
254	        endif;
255	        
256	
257	        /**
258	         * Se ho impostato file, filtro le traduzioni sulla base dei gruppi richiesti
259	         * e mi fermo 
260	         */
261	        if($this->arOptions["lang_source"] === 'file') {
262	            
263	            $groupFilter = explode(',', $this->groupList);
264	            
265	            $trads = array_filter($trads, function($rs) use ($groupFilter) {
266	                return in_array($rs['group_code'], $groupFilter);
267	            });
268	
269	            foreach ($trads as $key => $rs): 
270	                $this->arTrads[$rs['code']] = $rs['text_'.$this->lgSuff];
271	            endforeach;
272	
273	            return;
274	
275	        }
276	
277	
278	
279	        // Recupero traduzioni dal db
280	        $sql_gruppi = '';
281	        if (!empty($this->groupList)) {
282	            $sql_gruppi = " OR (";
283	            foreach (explode(",", $this->groupList) as $key => $gruppo) {
