452	    /**
453	     * Sostituisce variabili interne a valore link con quelle passate.
454	     * Se è un pattern, sostituisce ciascun parametro / espressione regolare
455	     * all'interno del link con l'indice corrispondente
456	     * passato in $replace_keys.
457	     * Es. link /it/news/{{(.*)}}.php
458	     */
459	    private function _parseL($link, $replace_keys = array()) {
460	
461	        // cerco e rimpiazzo le espressioni (le stringhe all'interno di "()"  )
462	        //  con i valori passati.
463	        foreach ($replace_keys as $replace): 
464	            $link = preg_replace("#\(([^\)]+)\)#", $replace, $link, 1);
465	        endforeach;
466	
467	        // rimpiazzo il delimitatore
468	        $link = str_replace('$','',$link);
469	
470	        return $link;
