664	    public function replaceVars($TEXT) {
665	        
666	        /// SOSTITUZIONE TAG LING
667	        $matches = array();
668	        preg_match_all('~\{LINK:(\w+)\}~', $TEXT, $matches);
669	                foreach ($matches[1] as $k => $trad_key_link) :
670	            $TEXT = str_replace($matches[0][$k], $this->returnL($trad_key_link) ,$TEXT);
671	        endforeach;
672	        
673	        
674	        /// SOSTITUZIONE TAG VAR
675	        $matches = array();
676	        preg_match_all('~\{VAR:(\w+)\}~', $TEXT, $matches);
677	        foreach ($matches[1] as $k => $var_name) :
678	            eval('global $'.$var_name.';');
679	
680	            $TEXT = str_replace($matches[0][$k], eval('return $'. $var_name . ';') , $TEXT);
681	        endforeach;
682	        
683	        return $TEXT;
684	    }
